const raw = $input.first().json;
const body = raw.body || raw;
const vendors = body.vendors || (body.website ? [{ website: body.website, vendor_name: body.vendor_name || '', linkedin_url: body.linkedin_url || '' }] : []);
if (!vendors.length) throw new Error('vendors array required');
const rapidapi_key = (body.rapidapi_key || process.env.RAPIDAPI_KEY || '').trim();
if (!rapidapi_key) throw new Error('rapidapi_key required');
const supabase_url = (body.supabase_url || process.env.SUPABASE_URL || '').trim();
const supabase_key = (body.supabase_key || process.env.SUPABASE_KEY || '').trim();

function normalizeDomain(value) {
  const rawValue = String(value || '').trim();
  if (!rawValue) return '';
  try {
    const candidate = /^https?:\/\//i.test(rawValue) ? rawValue : `https://${rawValue}`;
    return new URL(candidate).hostname.replace(/^www\./i, '').toLowerCase();
  } catch {
    return rawValue.replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0].toLowerCase();
  }
}

return vendors
  .map(v => ({
    json: {
      website: v.website,
      vendor_name: v.vendor_name || '',
      linkedin_url: v.linkedin_url || '',
      domain: normalizeDomain(v.website),
      rapidapi_key,
      supabase_url,
      supabase_key,
    }
  }))
  .filter(item => item.json.domain);

const response = $input.first().json;
const vendor = $('Split Vendors').first().json;
const website = vendor.website;
const vendor_name = vendor.vendor_name;
const statusCode = response.statusCode || response.$response?.statusCode || 0;
const payload = response.body || response.data || response;
const company = payload?.data || payload?.company || payload || {};
const extracted = {};

let providerError = '';
if (statusCode >= 400) {
  providerError = payload?.message || payload?.error || `http_${statusCode}`;
}
if (!providerError && company?.success === false) {
  providerError = company.message || company.error || 'provider_unavailable';
}
if (!providerError && payload?.success === false) {
  providerError = payload.message || payload.error || 'provider_unavailable';
}

const linkedinUrl = company.linkedin_url || company.linkedinUrl || company.linkedInUrl || company.url;
if (linkedinUrl && String(linkedinUrl).includes('linkedin.com')) {
  extracted.linkedin_url = linkedinUrl;
}

const employees = company.employees || company.executives || company.keyPeople || company.teamMembers || [];
const leadership = [];
let ceo_linkedin = '';
let ceo_name = '';

for (const person of employees) {
  const title = person.title || person.headline || person.role || '';
  const name = person.name || person.full_name || [person.firstName, person.lastName].filter(Boolean).join(' ');
  const profileUrl = person.linkedin_url || person.linkedinUrl || person.profile_url || person.profileUrl || person.url || '';
  if (!name) continue;
  leadership.push({ name, title, linkedin_url: profileUrl });
  if (!ceo_name && /ceo|chief executive|founder|co.?founder/i.test(title)) {
    ceo_name = name;
    ceo_linkedin = profileUrl;
  }
}

if (leadership.length) extracted.leadership = leadership;
if (ceo_name) extracted.ceo_name = ceo_name;
if (ceo_linkedin) extracted.ceo_linkedin = ceo_linkedin;

const has_data = Object.keys(extracted).length > 0;
return [{ json: { website, vendor_name, extracted, has_data, error: providerError, status_code: statusCode, pipeline_name: 'csp-linkedin-enrichment' } }];
